// Package genheader holds the one line every generated file's header carries
// directly after its "Code generated by the schema compiler ... DO NOT EDIT."
// line: where the compiler lives, and how the file is regenerated.
//
// A person or an AI assistant who meets a generated file in someone else's
// game repository cannot find the tool from "the schema compiler" alone: the
// phrase is not searchable and names no place. This line names the place. It
// is a comment and nothing else — no generated code, protocol id or wire byte
// depends on it — and its text exists once, here, so every emitter writes the
// same words and a change to them is one edit.
package genheader

// URL is the schema compiler's home.
const URL = "https://github.com/mas-bandwidth/schema"

// Head and Tail are the line's two halves. A target whose line-length limit
// cannot hold the whole line writes them on two comment lines, with the URL
// whole on the first: Lua (luacheck's 120 columns, W631) and Java (the
// emitter's own 100-column canonical form, which would otherwise re-flow the
// line at an arbitrary word).
const (
	Head = "Schema: " + URL + " —"
	Tail = "to change this file, edit the .schema source and run `schema generate`."
)

// Text is the whole line, without its comment leader.
const Text = Head + " " + Tail

// Line returns the line under a comment leader — "//", "#", "--", or the
// indentation that continues a C block comment ("  ", so the text lines up
// under "/* ") — with its newline.
func Line(lead string) string {
	return lead + " " + Text + "\n"
}

// Wrapped returns the line as two comment lines under lead, the URL whole on
// the first, for a target whose line-length gate the one-line form exceeds.
func Wrapped(lead string) string {
	return lead + " " + Head + "\n" + lead + " " + Tail + "\n"
}
